import { spawn } from 'node:child_process';
import { writeFileSync } from 'node:fs';
const page = 'file://' + process.argv[2];
const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  ['--headless=new', '--remote-debugging-port=9333', '--user-data-dir=/tmp/actcheck/profile', '--no-first-run', 'about:blank'], { stdio: 'ignore' });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let targets;
for (let i = 0; i < 50; i++) { try { targets = await (await fetch('http://127.0.0.1:9333/json')).json(); break; } catch { await sleep(200); } }
const ws = new WebSocket(targets.find((t) => t.type === 'page').webSocketDebuggerUrl);
await new Promise((r) => ws.addEventListener('open', r));
let id = 0; const pending = new Map(); const logs = [];
ws.addEventListener('message', (m) => { const d = JSON.parse(m.data);
  if (d.id && pending.has(d.id)) { pending.get(d.id)(d); pending.delete(d.id); }
  if (d.method === 'Runtime.exceptionThrown') logs.push('EXCEPTION ' + JSON.stringify(d.params.exceptionDetails.exception?.description));
  if (d.method === 'Runtime.consoleAPICalled') logs.push('console ' + d.params.args.map((a) => a.value).join(' ')); });
const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
const ev = async (expr) => (await send('Runtime.evaluate', { expression: expr, returnByValue: true })).result.result.value;
const key = async (k, code, vk, text) => { await send('Input.dispatchKeyEvent', { type: 'keyDown', key: k, code, windowsVirtualKeyCode: vk, text }); await send('Input.dispatchKeyEvent', { type: 'keyUp', key: k, code, windowsVirtualKeyCode: vk }); };
const type = async (s) => { for (const ch of s) await send('Input.dispatchKeyEvent', { type: 'char', text: ch }); };
const click = async (sel) => { const r = await ev(`(()=>{const b=document.querySelector('${sel}').getBoundingClientRect();return [b.x+b.width/2,b.y+b.height/2]})()`);
  for (const t of ['mousePressed', 'mouseReleased']) await send('Input.dispatchMouseEvent', { type: t, x: r[0], y: r[1], button: 'left', clickCount: 1 }); };
const setSelect = (sel, v) => ev(`(()=>{const s=document.querySelector('${sel}');s.value='${v}';s.dispatchEvent(new Event('change'))})()`);
const setDate = (sel, v) => ev(`(()=>{const s=document.querySelector('${sel}');s.value='${v}';s.dispatchEvent(new Event('input'))})()`);
const state = (label) => ev(`(()=>({label:${JSON.stringify(label)},count:document.getElementById('activity-count').textContent,
  types:[...new Set([...document.querySelectorAll('#activity-table tbody tr:not([hidden]) td:nth-child(2)')].map(t=>t.textContent))].join(', '),
  dates:[...document.querySelectorAll('#activity-table tbody tr:not([hidden]) td:nth-child(1)')].map(t=>t.textContent).filter((_,i,a)=>i==0||i==a.length-1).join(' .. '),
  err:!document.getElementById('filter-date-error').hidden, invalid:document.getElementById('filter-to').getAttribute('aria-invalid'),
  described:document.getElementById('filter-to').getAttribute('aria-describedby'),
  range:document.getElementById('filter-range').value, from:document.getElementById('filter-from').value, to:document.getElementById('filter-to').value,
  search:document.getElementById('filter-search').value, clearShown:!document.getElementById('filter-search-clear').hidden,
  focus:document.activeElement.id||document.activeElement.tagName}))()`);
const out = [];
await send('Runtime.enable'); await send('Page.enable');
await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 900, deviceScaleFactor: 1, mobile: false });
await send('Page.navigate', { url: page }); await sleep(800);
out.push(await state('initial'));
await setSelect('#filter-type', 'security'); out.push(await state('type=All security changes'));
await setSelect('#filter-type', 'Sign-in failed'); out.push(await state('type=Sign-in failed'));
await setSelect('#filter-type', 'all');
await setSelect('#filter-range', '7'); out.push(await state('range=Last 7 days'));
await setSelect('#filter-range', 'any'); out.push(await state('range=Any time'));
await setDate('#filter-from', '2026-09-21'); await setDate('#filter-to', '2026-09-27'); out.push(await state('custom week 21-27 Sep'));
await setSelect('#filter-type', 'security'); out.push(await state('week + security'));
await setSelect('#filter-type', 'all');
await setDate('#filter-to', '2026-09-20'); out.push(await state('to before from'));
await setDate('#filter-to', '2026-09-21'); out.push(await state('same day (valid)'));
await setSelect('#filter-range', 'any');
await click('#filter-search'); await type('madrid'); out.push(await state('typed "madrid"'));
await key('Escape', 'Escape', 27); out.push(await state('after Escape'));
await type('frank'); await click('#filter-search-clear'); out.push(await state('clicked clear button'));
await type('porto'); await key('Enter', 'Enter', 13, '\r'); await sleep(300); out.push({ ...(await state('Enter in search')), url: await ev('location.href') });
