await send('Page.navigate', { url: page }); await sleep(600);
await click('#filter-search'); await type('x');
const shot = async (f) => writeFileSync(f, Buffer.from((await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: true })).result.data, 'base64'));
await shot('/tmp/actcheck/desktop.png');
await send('Emulation.setDeviceMetricsOverride', { width: 320, height: 900, deviceScaleFactor: 2, mobile: true });
await sleep(300);
out.push({ label: '320px', docWidth: await ev('document.documentElement.scrollWidth'),
  filterBarWidth: await ev(`document.getElementById('activity-filters').scrollWidth`),
  widestFilterControl: await ev(`Math.max(...[...document.querySelectorAll('#activity-filters select,#activity-filters input')].map(e=>e.getBoundingClientRect().right))`),
  clearBtn: await ev(`(()=>{const b=document.getElementById('filter-search-clear').getBoundingClientRect();return b.width+'x'+b.height})()`) });
await ev(`document.querySelector('#activity-table').style.display='none'`);
out.push({ label: '320px, table hidden', docWidth: await ev('document.documentElement.scrollWidth') });
await ev(`document.querySelector('#activity-table').style.display=''`);
await shot('/tmp/actcheck/mobile.png');
// No-JS check.
await send('Emulation.setScriptExecutionDisabled', { value: true });
await send('Page.navigate', { url: page }); await sleep(600);
out.push({ label: 'JS disabled', filterBarVisible: await (async () => { await send('Emulation.setScriptExecutionDisabled', { value: false }); return ev(`getComputedStyle(document.getElementById('activity-filters')).display`); })() });
out.push({ label: 'errors', logs });
console.log(JSON.stringify(out, null, 1));
ws.close(); chrome.kill();
